template <class RangeType>
auto vector(RangeType _r) {
  using T = std::ranges::range_value_t<RangeType>;
  std::vector<T> res;
  for (auto e : _r) {
    res.emplace_back(std::move(e));
  }
  return res;
}

template <class T>
std::string get_tablename() noexcept {
  using Type = std::remove_cvref_t<T>;

  constexpr bool has_tablename = requires {
    { Type::tablename } -> std::convertible_to<std::string>;
  };

  constexpr bool has_viewname = requires {
    { Type::viewname } -> std::convertible_to<std::string>;
  };

  if constexpr (has_tablename) {
    static_assert(
        !has_viewname,
        "A struct can either have a tablename or a viewname, but not both.");
    return std::string(Type::tablename);

  } else if constexpr (has_viewname) {
    return std::string(Type::viewname);

  } else {
    return internal::remove_namespaces(rfl::type_name_t<Type>().str());
  }
}

template <class T>
std::optional<std::string> get_schema() noexcept {
  using Type = std::remove_cvref_t<T>;
  if constexpr (has_schema<Type>) {
    return std::string(Type::schema);
  } else {
    return std::nullopt;
  }
}

template <class T, class ConditionType>
std::optional<dynamic::Condition> to_condition(const ConditionType& _cond) {
  return ToCondition<T, std::remove_cvref_t<ConditionType>>{}(_cond);
}

template <class LimitType>
std::optional<dynamic::Limit> to_limit(const LimitType& _limit) {
  if constexpr (std::is_same_v<std::remove_cvref_t<LimitType>, Nothing>) {
    return std::nullopt;

  } else if constexpr (std::is_same_v<std::remove_cvref_t<LimitType>, Limit>) {
    return _limit;

  } else {
    static_assert(rfl::always_false_v<LimitType>, "Unsupported type");
  }
}

