inline rfl::Unexpected<Error> make_error(const Ref<MYSQL>& _conn) noexcept {
  return error("MySQL error (" + std::to_string(mysql_errno(_conn.get())) +
               ") [" + mysql_sqlstate(_conn.get()) + "] " +
               mysql_error(_conn.get()));
}

