                         std::is_same_v<T, dynamic::types::Text> ||
                         std::is_same_v<T, dynamic::types::VarChar> ||
                         std::is_same_v<T, dynamic::types::Date> ||
                         std::is_same_v<T, dynamic::types::Timestamp> ||
