                           .and_then(create_table<Children> | if_not_exists)
                           .and_then(insert(std::ref(people1)))
                           .and_then(insert(std::ref(children)))
                           .and_then(commit)
                           .and_then(sqlgen::read<std::vector<Person>>)
                           .value();

