int main() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // 步骤1: 创建查询，从 Person 表选择所有字段
  auto person_query = select_from<Person>("id"_c, "first_name"_c, "last_name"_c, "age"_c);

  // 步骤2: 创建视图，应用 if_not_exists 选项
  auto create_view_stmt = create_as<PersonView>(person_query) | if_not_exists;

  // 步骤3: 生成创建视图的 SQL 语句
  std::string create_view_sql = sqlite::to_sql(create_view_stmt);

  // 步骤4: 创建从 PersonView 视图选择的查询
  auto view_query = select_from<PersonView>("id"_c, "first_name"_c, "last_name"_c, "age"_c);

  // 步骤5: 生成查询视图的 SQL 语句
  std::string select_view_sql = sqlite::to_sql(view_query);

  // 输出 SQL 语句（示例）
  // std::cout << "Create View SQL: " << create_view_sql << std::endl;
  // std::cout << "Select View SQL: " << select_view_sql << std::endl;

  return 0;
}

