  sqlgen::write(conn, user);

  // Read all users
  const auto users = sqlgen::read<std::vector<User>>(conn).value();

  EXPECT_EQ(users.size(), 1);
  EXPECT_EQ(users.at(0).name, "John");
  EXPECT_EQ(users.at(0).age, 30);
}

